entries.print_conv_text:
my ($a,$b,$c)=split ' ',$val;
if ($self->{Model} =~ /^E-1\b/) {
    $a-=$b; $c-=$b;
    return "CS$a (min CS0, max CS$c)";
} else {
    return "$a (min $b, max $c)";
}

my ($a,$b,$c,$d,$e,$f) = split ' ',$val;
if ($b) {
    $b = ', Shot ' . $b;
} else {
    $b = '';
}
if (not defined $e or $e == 4) {   #KG: personally, I'd like to skip 'Electronic shutter' since this is the defacto default setting
    $e = '';
} else {
    $e = '; ' . ({ 0 => 'Mechanical shutter' , 2 => 'Anti-shock' }->{$e} || "Unknown ($e)");
}
if ($a == 5 and defined $c) {
    $a = DecodeBits($c, { #6
        0 => 'AE',
        1 => 'WB',
        2 => 'FL',
        3 => 'MF',
        4 => 'ISO', #forum8906
        5 => 'AE Auto', #forum8906
        6 => 'Focus', #PH
    }) . ' Bracketing';
    $a =~ s/, /+/g;
} elsif ($f) { #25
      # for newer models (E-M1 and later) look at byte 6 for other shooting modes
      my %f = (
          # Mechanical shutter modes
          0x01 => 'Single Shot',
          0x02 => 'Sequential L',
          0x03 => 'Sequential H',
          0x07 => 'Sequential',
          # Anti-shock modes
          0x11 => 'Single Shot',
          0x12 => 'Sequential L',
          0x13 => 'Sequential H',
          0x14 => 'Self-Timer 12 sec',
          0x15 => 'Self-Timer 2 sec',
          0x16 => 'Custom Self-Timer',
          0x17 => 'Sequential',
          # Electronical shutter modes
          0x21 => 'Single Shot',
          0x22 => 'Sequential L',
          0x23 => 'Sequential H',
          0x24 => 'Self-Timer 2 sec',
          0x25 => 'Self-Timer 12 sec',
          0x26 => 'Custom Self-Timer',
          0x27 => 'Sequential',
          0x28 => 'Sequential SH1',
          0x29 => 'Sequential SH2',
          0x30 => 'HighRes Shot',  # only E-M models
          0x41 => 'ProCap H',
          0x42 => 'ProCap L',
          0x43 => 'ProCap',
          0x48 => 'ProCap SH1',
          0x49 => 'ProCap SH2',
      );
      $a = $f{$f} || "Unknown ($f)";
} else {
      my %a = (
          0 => 'Single Shot',
          1 => 'Continuous Shooting',
          2 => 'Exposure Bracketing',
          3 => 'White Balance Bracketing',
          4 => 'Exposure+WB Bracketing', #6
      );
      $a = $a{$a} || "Unknown ($a)";
}
return "$a$b$e";

my ($a,$b) = split ' ',$val;
return 'Off' unless $a;
my %a = (
    1 => 'Left to Right',
    2 => 'Right to Left',
    3 => 'Bottom to Top',
    4 => 'Top to Bottom',
);
return(($a{$a} || "Unknown ($a)") . ', Shot ' . $b);

my ($a,$b) = split ' ',$val;
return 'Off' unless $a;
$b = ($b == 1) ? 'Full' : "1/$b";
return "On ($b strength)";
